#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int num, score; struct Node *next; } Node;
Node *read_list(int n) {
    Node *head = NULL;
    for (int i = 0; i < n; i++) {
        Node *node = malloc(sizeof(*node));
        if (!node) exit(1);
        scanf("%d%d", &node->num, &node->score);
        Node **link = &head;
        while (*link && (*link)->num < node->num) link = &(*link)->next;
        node->next = *link; *link = node;
    }
    return head;
}

int main(void) {
    int n, m;
    scanf("%d", &n); Node *a = read_list(n);
    scanf("%d", &m); Node *b = read_list(m);
    Node *head = NULL, **tail = &head;
    while (a || b) {
        Node **choice = !b || (a && a->num < b->num) ? &a : &b;
        *tail = *choice; *choice = (*choice)->next;
        tail = &(*tail)->next;
    }
    *tail = NULL;
    if (!head) puts("EMPTY");
    while (head) {
        printf("%d %d\n", head->num, head->score);
        Node *next = head->next; free(head); head = next;
    }
    return 0;
}
